window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8a3444b4de2bb76c"]={"versions": [{"id": "FIG-8a3444b4de2bb76c", "releases": ["R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) zur Spezifikation einer Sub-Aktivität/eines Funktionsschritts.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR E2E Protocol (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation, gültig für Classic & Adaptive Platform).</li>\n<li><strong>Technischer Zweck:</strong> Normative Definition des Einzelschritts „Write DataID“ innerhalb der generischen senderseitigen Schutzfunktion <code>E2E_PXXProtect()</code>. Dient der Absicherung gegen Kommunikationsfehler (insbesondere Masquerading/Addressing Errors) gem. ISO 26262 ASIL D durch explizites Einbetten der Datenidentifikation in den Serialisierungs-Bytestrom.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionen:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Übergeordnete E2E-Schutzfunktion. Der Platzhalter <code>XX</code> steht stellvertretend für ein konkretes Profil (z. B. Profile 04, 05, 07, 22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>Config</code> (Pointer auf <code>E2E_PXXConfigType</code>): Enthält statische Konfigurationsparameter, hier spezifisch <code>Config-&gt;DataID</code>.</li>\n<li><code>Data</code> (<code>uint8*</code>): Linearer Nutzdatenpuffer (Byte-Array / Serialization Buffer) der PDU.</li>\n<li><strong>Spezifikations-Konstanten / Offsets (profildividuell definiert):</strong></li>\n<li><code>PXXDATAID_LEN</code>: Länge der DataID in Bytes (z. B. 2 oder 4 Bytes je nach Profil).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifischer relativer Byte-Offset der DataID innerhalb des E2E-Headers.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Byte-/Bit-Offset des E2E-Headers innerhalb von <code>Data</code> (<code>Config-&gt;Offset</code>).</li>\n<li><strong>Adressierungsbereich (UML-Note):</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Zielbereich} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\dots \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Sub-Schritt nach erfolgreicher Parametervalidierung und ggf. dem Schritt „Write Counter“.</li>\n<li><strong>Action Node („Copy parameter Config->DataID to bytestring Data in Big Endian order“):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone, atomare Kopieroperation: Der ganzzahlige Wert <code>Config-&gt;DataID</code> wird in Network Byte Order (<strong>Big Endian</strong>, MSB first) in das Byte-Array <code>Data</code> geschrieben.</li>\n<li>Adressierung erfolgt strikt über das berechnete Byte-Intervall gemäß Note-Bedingung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Verlassen des Sub-Schritts; Übergang zu den nachfolgenden Schutzschritten (z. B. Berechnung und Schreiben der CRC über Daten und Header).</li>\n<li><strong>Fehlerpfade:</strong> Keine lokalen Callbacks (kein Det/Dem-Aufruf innerhalb dieser Aktion); Pointer-Gültigkeit und Pufferlängen werden im Entry-Guard von <code>E2E_PXXProtect()</code> vorab verifiziert.</li>\n</ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Pflicht:</strong> Unabhängig von der Host-Architektur (Little Endian bei ARM Cortex-R/M/A oder TriCore) muss die DataID zwingend in Big-Endian-Reihenfolge serialisiert werden (Bit-Shifting/Byte-Swapping erforderlich).</li>\n<li><strong>Puffer-Bounds-Safety:</strong> Der Stack/Treiber-Entwickler muss sicherstellen, dass <code>Data</code> mindestens eine allokierte Größe von $\\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN}$ aufweist, um Pufferüberläufe zu verhindern.</li>\n<li><strong>Profilspezifische Gültigkeit:</strong> Gilt ausschließlich für Profile bzw. Modi, bei denen die DataID physisch im PDU-Payload übertragen wird (im Gegensatz zu impliziten Profilen, bei denen die DataID lediglich als Seed/Startwert in die CRC-Berechnung einfließt).</li>\n<li><strong>Anforderungskonformität:</strong> Verbindliche Implementierungsvorgabe für SWS/PRS-Anforderung <code>[PRS_E2E_01214]</code> zur Erfüllung von <code>[RS_E2E_08539]</code>.</li>\n</ul>"}, {"id": "FIG-c0e4285826003299", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) zur Spezifikation einer Sub-Aktivität/eines Funktionsschritts.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR E2E Protocol (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation, gültig für Classic & Adaptive Platform).</li>\n<li><strong>Technischer Zweck:</strong> Normative Definition des Einzelschritts „Write DataID“ innerhalb der generischen senderseitigen Schutzfunktion <code>E2E_PXXProtect()</code>. Dient der Absicherung gegen Kommunikationsfehler (insbesondere Masquerading/Addressing Errors) gem. ISO 26262 ASIL D durch explizites Einbetten der Datenidentifikation in den Serialisierungs-Bytestrom.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionen:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Übergeordnete E2E-Schutzfunktion. Der Platzhalter <code>XX</code> steht stellvertretend für ein konkretes Profil (z. B. Profile 04, 05, 07, 22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>Config</code> (Pointer auf <code>E2E_PXXConfigType</code>): Enthält statische Konfigurationsparameter, hier spezifisch <code>Config-&gt;DataID</code>.</li>\n<li><code>Data</code> (<code>uint8*</code>): Linearer Nutzdatenpuffer (Byte-Array / Serialization Buffer) der PDU.</li>\n<li><strong>Spezifikations-Konstanten / Offsets (profildividuell definiert):</strong></li>\n<li><code>PXXDATAID_LEN</code>: Länge der DataID in Bytes (z. B. 2 oder 4 Bytes je nach Profil).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifischer relativer Byte-Offset der DataID innerhalb des E2E-Headers.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Byte-/Bit-Offset des E2E-Headers innerhalb von <code>Data</code> (<code>Config-&gt;Offset</code>).</li>\n<li><strong>Adressierungsbereich (UML-Note):</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Zielbereich} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\dots \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Sub-Schritt nach erfolgreicher Parametervalidierung und ggf. dem Schritt „Write Counter“.</li>\n<li><strong>Action Node („Copy parameter Config->DataID to bytestring Data in Big Endian order“):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone, atomare Kopieroperation: Der ganzzahlige Wert <code>Config-&gt;DataID</code> wird in Network Byte Order (<strong>Big Endian</strong>, MSB first) in das Byte-Array <code>Data</code> geschrieben.</li>\n<li>Adressierung erfolgt strikt über das berechnete Byte-Intervall gemäß Note-Bedingung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Verlassen des Sub-Schritts; Übergang zu den nachfolgenden Schutzschritten (z. B. Berechnung und Schreiben der CRC über Daten und Header).</li>\n<li><strong>Fehlerpfade:</strong> Keine lokalen Callbacks (kein Det/Dem-Aufruf innerhalb dieser Aktion); Pointer-Gültigkeit und Pufferlängen werden im Entry-Guard von <code>E2E_PXXProtect()</code> vorab verifiziert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Pflicht:</strong> Unabhängig von der Host-Architektur (Little Endian bei ARM Cortex-R/M/A oder TriCore) muss die DataID zwingend in Big-Endian-Reihenfolge serialisiert werden (Bit-Shifting/Byte-Swapping erforderlich).</li>\n<li><strong>Puffer-Bounds-Safety:</strong> Der Stack/Treiber-Entwickler muss sicherstellen, dass <code>Data</code> mindestens eine allokierte Größe von $\\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN}$ aufweist, um Pufferüberläufe zu verhindern.</li>\n<li><strong>Profilspezifische Gültigkeit:</strong> Gilt ausschließlich für Profile bzw. Modi, bei denen die DataID physisch im PDU-Payload übertragen wird (im Gegensatz zu impliziten Profilen, bei denen die DataID lediglich als Seed/Startwert in die CRC-Berechnung einfließt).</li>\n<li><strong>Anforderungskonformität:</strong> Verbindliche Implementierungsvorgabe für SWS/PRS-Anforderung <code>[PRS_E2E_01214]</code> zur Erfüllung von <code>[RS_E2E_08539]</code>.</li>\n</ul>"}, {"id": "FIG-f2581d6713dffa98", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Aktivitätsdiagramm (Activity Diagram) zur Spezifikation einer Sub-Aktivität/eines Funktionsschritts.</li>\n<li><strong>Architektur-Kontext:</strong> AUTOSAR E2E Protocol (<code>AUTOSAR_FO_PRS_E2EProtocol</code>, Foundation, gültig für Classic & Adaptive Platform).</li>\n<li><strong>Technischer Zweck:</strong> Normative Definition des Einzelschritts „Write DataID“ innerhalb der generischen senderseitigen Schutzfunktion <code>E2E_PXXProtect()</code>. Dient der Absicherung gegen Kommunikationsfehler (insbesondere Masquerading/Addressing Errors) gem. ISO 26262 ASIL D durch explizites Einbetten der Datenidentifikation in den Serialisierungs-Bytestrom.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteure / Funktionen:</strong></li>\n<li><code>E2E_PXXProtect()</code>: Übergeordnete E2E-Schutzfunktion. Der Platzhalter <code>XX</code> steht stellvertretend für ein konkretes Profil (z. B. Profile 04, 05, 07, 22).</li>\n<li><strong>Datenstrukturen & Parameter:</strong></li>\n<li><code>Config</code> (Pointer auf <code>E2E_PXXConfigType</code>): Enthält statische Konfigurationsparameter, hier spezifisch <code>Config-&gt;DataID</code>.</li>\n<li><code>Data</code> (<code>uint8*</code>): Linearer Nutzdatenpuffer (Byte-Array / Serialization Buffer) der PDU.</li>\n<li><strong>Spezifikations-Konstanten / Offsets (profildividuell definiert):</strong></li>\n<li><code>PXXDATAID_LEN</code>: Länge der DataID in Bytes (z. B. 2 oder 4 Bytes je nach Profil).</li>\n<li><code>PXXDATAID_POS</code>: Profilspezifischer relativer Byte-Offset der DataID innerhalb des E2E-Headers.</li>\n<li><code>Offset</code>: Konfigurierter Basis-Byte-/Bit-Offset des E2E-Headers innerhalb von <code>Data</code> (<code>Config-&gt;Offset</code>).</li>\n<li><strong>Adressierungsbereich (UML-Note):</strong></li>\n</ul>\n<p class=\"fig-p\">$$\\text{Zielbereich} = [\\text{Offset} + \\text{PXXDATAID\\_POS} \\dots \\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN} - 1]$$</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initial Node:</strong> Eintritt in den Sub-Schritt nach erfolgreicher Parametervalidierung und ggf. dem Schritt „Write Counter“.</li>\n<li><strong>Action Node („Copy parameter Config->DataID to bytestring Data in Big Endian order“):</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Synchrone, atomare Kopieroperation: Der ganzzahlige Wert <code>Config-&gt;DataID</code> wird in Network Byte Order (<strong>Big Endian</strong>, MSB first) in das Byte-Array <code>Data</code> geschrieben.</li>\n<li>Adressierung erfolgt strikt über das berechnete Byte-Intervall gemäß Note-Bedingung.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Activity Final Node:</strong> Verlassen des Sub-Schritts; Übergang zu den nachfolgenden Schutzschritten (z. B. Berechnung und Schreiben der CRC über Daten und Header).</li>\n<li><strong>Fehlerpfade:</strong> Keine lokalen Callbacks (kein Det/Dem-Aufruf innerhalb dieser Aktion); Pointer-Gültigkeit und Pufferlängen werden im Entry-Guard von <code>E2E_PXXProtect()</code> vorab verifiziert.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Endianness-Pflicht:</strong> Unabhängig von der Host-Architektur (Little Endian bei ARM Cortex-R/M/A oder TriCore) muss die DataID zwingend in Big-Endian-Reihenfolge serialisiert werden (Bit-Shifting/Byte-Swapping erforderlich).</li>\n<li><strong>Puffer-Bounds-Safety:</strong> Der Stack/Treiber-Entwickler muss sicherstellen, dass <code>Data</code> mindestens eine allokierte Größe von $\\text{Offset} + \\text{PXXDATAID\\_POS} + \\text{PXXDATAID\\_LEN}$ aufweist, um Pufferüberläufe zu verhindern.</li>\n<li><strong>Profilspezifische Gültigkeit:</strong> Gilt ausschließlich für Profile bzw. Modi, bei denen die DataID physisch im PDU-Payload übertragen wird (im Gegensatz zu impliziten Profilen, bei denen die DataID lediglich als Seed/Startwert in die CRC-Berechnung einfließt).</li>\n<li><strong>Anforderungskonformität:</strong> Verbindliche Implementierungsvorgabe für SWS/PRS-Anforderung <code>[PRS_E2E_01214]</code> zur Erfüllung von <code>[RS_E2E_08539]</code>.</li>\n</ul>"}], "trans": [{"from": "FIG-8a3444b4de2bb76c", "to": "FIG-c0e4285826003299", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Im oberen Randbereich wurden Schnitt- bzw. Artefaktfragmente aus der umgebenden Spezifikationsseite entfernt.</li>\n<li>Im zentralen Aktionsknoten wurde der Zeilenumbruch der Beschriftung geändert: „Endian“ rutschte von der ersten Zeile in die zweite Zeile („Copy parameter Config->DataID to bytestring Data in Big“ / „Endian order.“).</li>\n</ul>"}, {"from": "FIG-c0e4285826003299", "to": "FIG-f2581d6713dffa98", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
